import type { CartState } from "@/types";

/** localStorage key holding the cart id (generated by the cart provider). */
export const CART_ID_STORAGE_KEY = "np-cart-id";

/** Cookie holding mock-cart state — the only server-readable cart store. */
export const MOCK_CART_COOKIE = "np-cart";

/**
 * Demo discount codes for mock mode (percent off). When Shopify is
 * connected, codes are validated by Shopify itself — this map is unused.
 */
export const MOCK_DISCOUNT_CODES: Readonly<Record<string, number>> = {
  COZY10: 0.1,
  WELCOME15: 0.15,
};

/** Fresh empty cart for the given backend. */
export function emptyCart(mode: CartState["mode"] = "mock"): CartState {
  const zero = { amount: 0, currencyCode: "USD" };
  return {
    id: null,
    mode,
    lines: [],
    totalQuantity: 0,
    subtotal: zero,
    total: zero,
    discount: null,
    checkoutUrl: null,
  };
}
